$next=apply_operation($current['state'],'payment',['chargeId'=>'q2','amount'=>50,'receiptDate'=>null]);save_state(['state'=>$next,'revision'=>1,'requestId'=>'test_conflict','action'=>'synthetic'],$u);reject(fn()=>save_state(['state'=>$current['state'],'revision'=>1,'requestId'=>'stale'],$u),'stale revision accepted');
